import {readingReportRows,readingReportCSV} from './reading-report.mjs';
export function createMaterialReadingUI({e}){
 let overviewData=null,csvURL=null;
 const hidden=(n,v)=>'<input type="hidden" name="'+n+'" value="'+e(v)+'">',date=v=>new Date(v).toLocaleString('en-GB',{timeZone:'Asia/Tashkent',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
 function student(r){const read=r.reading||{};return '<section class="vle-note"><strong>'+(read.confirmed?'Reading confirmed':read.updatedSinceRead?'Updated material · please read again':'Confirm your reading')+'</strong><p>'+(read.confirmed?'You confirmed this version on '+e(date(read.confirmedAt))+'.':read.updatedSinceRead?'This material has changed since your confirmation. Read the current version, then confirm below.':'Read this material, then confirm below.')+'</p><form data-vle="resource-read">'+hidden('id',r.id)+hidden('expectedRevision',r.revision||1)+hidden('read',!read.confirmed)+'<button type="submit" class="btn '+(read.confirmed?'':'primary')+'">'+(read.confirmed?'Mark as not read':"I've read this")+'</button></form></section>';}
 function teacher(d){if(!d)return '';return '<details class="vle-panel"><summary>Reading confirmations · '+d.confirmed+' / '+d.total+'</summary><p>Students confirm when they have read the current version.</p><label class="vle-field">Show<select data-material-reader-filter aria-label="Filter reading confirmations"><option value="pending">Not yet confirmed</option><option value="all">All students</option><option value="confirmed">Confirmed</option><option value="updated">Updated since confirmation</option></select></label><p role="status" data-material-reader-count></p><div class="material-reader-list table-wrap"><table class="data-table"><thead><tr><th scope="col">Student</th><th scope="col">Current version</th><th scope="col">Last confirmation</th></tr></thead><tbody>'+d.rows.map(r=>'<tr data-material-reader="'+r.status+'"><td>'+e(r.name)+'</td><td>'+(r.status==='confirmed'?'Confirmed':r.status==='updated'?'Updated · read again':'Not confirmed')+'</td><td>'+(r.confirmedAt?e(date(r.confirmedAt)):'—')+'</td></tr>').join('')+'</tbody></table></div></details>';}
 function studentReport(d,link){return '<p>'+link('← Class reading overview',{class:d.classId,tab:'apps',materialReport:'1'})+'</p><section class="vle-panel"><h3>'+e(d.studentName)+' · Reading</h3><p>'+d.confirmed+' / '+d.total+' current versions confirmed. Select a material to open its guide and class confirmation report.</p>'+(!d.total?'<p>No materials have been shared with this class yet.</p>':'<label class="vle-field">Show<select data-material-reader-filter aria-label="Filter student reading materials"><option value="pending">Reading to confirm</option><option value="all">All materials</option><option value="confirmed">Confirmed</option><option value="updated">Updated since confirmation</option></select></label><p role="status" data-material-reader-count data-reader-kind="material"></p><div class="material-reader-list table-wrap"><table class="data-table"><thead><tr><th scope="col">Material</th><th scope="col">Current version</th><th scope="col">Last confirmation</th></tr></thead><tbody>'+d.rows.map(r=>'<tr data-material-reader="'+r.status+'"><td>'+link(r.title,{class:d.classId,tab:'apps',material:r.id})+'<br><small>'+e(r.topic)+'</small></td><td>'+(r.status==='confirmed'?'Confirmed':r.status==='updated'?'Updated · read again':'Not confirmed')+'</td><td>'+(r.confirmedAt?e(date(r.confirmedAt)):'—')+'</td></tr>').join('')+'</tbody></table></div><p class="vle-note">These are student reading confirmations. Teachers cannot confirm on a student’s behalf. Archived materials are excluded.</p>')+'</section>';}
 function overview(d,link){overviewData=d;return '<p>'+link('← All class materials',{class:d.classId,tab:'apps'})+'</p><section class="vle-panel"><h3>Class reading overview</h3><p>'+d.totalMaterials+' available '+(d.totalMaterials===1?'material':'materials')+' · Confirmations apply to the current version. Archived materials are excluded.</p>'+(!d.totalMaterials?'<p>No materials have been shared with this class yet.</p>':'<div class="community-filters"><label class="vle-field">Show<select data-reading-overview-filter aria-label="Filter class reading"><option value="pending">Students with reading to confirm</option><option value="all">All students</option><option value="complete">All reading confirmed</option><option value="updated">Updated material to read again</option></select></label><label class="vle-field">Find a student<input type="search" data-reading-overview-search aria-label="Find a student in reading report" placeholder="Student name" maxlength="120"></label><button type="button" class="btn" data-reading-overview-download>Download filtered CSV</button></div><p role="status" data-reading-overview-count></p><div class="material-reader-list table-wrap"><table class="data-table"><thead><tr><th scope="col">Student</th><th scope="col">Confirmed</th><th scope="col">To confirm</th><th scope="col">Updated</th></tr></thead><tbody>'+d.rows.map(r=>'<tr data-reading-overview-pending="'+r.pending+'" data-reading-overview-updated="'+r.updated+'"><td>'+link(r.name,{class:d.classId,tab:'apps',materialReport:'1',readingStudent:r.id})+'</td><td>'+r.confirmed+' / '+d.totalMaterials+'</td><td>'+r.pending+'</td><td>'+r.updated+'</td></tr>').join('')+'</tbody></table></div><details><summary>By material</summary><div class="material-reader-list table-wrap"><table class="data-table"><thead><tr><th scope="col">Material</th><th scope="col">Confirmed</th></tr></thead><tbody>'+d.materials.map(m=>'<tr><td>'+link(m.title,{class:d.classId,tab:'apps',material:m.resourceId})+'</td><td>'+m.confirmed+' / '+m.total+'</td></tr>').join('')+'</tbody></table></div></details>')+'</section>';}
 function bind(root){const overviewFilter=root.querySelector('[data-reading-overview-filter]');if(overviewFilter&&overviewData){const data=overviewData,search=root.querySelector('[data-reading-overview-search]'),download=root.querySelector('[data-reading-overview-download]'),filters=()=>({status:overviewFilter.value,search:search.value});const update=()=>{const shown=new Set(readingReportRows(data,filters()).map(r=>r.id));root.querySelectorAll('[data-reading-overview-pending]').forEach((row,index)=>{row.hidden=!shown.has(data.rows[index].id);});root.querySelector('[data-reading-overview-count]').textContent=shown.size?shown.size+' '+(shown.size===1?'student':'students')+' in this view.':'No students match these filters.';download.disabled=!shown.size;};overviewFilter.addEventListener('change',update);search.addEventListener('input',update);download.addEventListener('click',()=>{if(!readingReportRows(data,filters()).length)return;if(csvURL)URL.revokeObjectURL(csvURL);csvURL=URL.createObjectURL(new Blob([readingReportCSV(data,filters())],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=csvURL;a.download='WIST-class-reading.csv';a.click();});update();}const select=root.querySelector('[data-material-reader-filter]');if(!select)return;const update=()=>{let count=0;root.querySelectorAll('[data-material-reader]').forEach(row=>{const status=row.dataset.materialReader,show=select.value==='all'||select.value==='pending'&&status!=='confirmed'||select.value===status;row.hidden=!show;if(show)count++;});const counter=root.querySelector('[data-material-reader-count]'),kind=counter.dataset.readerKind||'student';counter.textContent=count?count+' '+kind+(count===1?'':'s')+' in this view.':'No '+kind+'s match this filter.';};select.addEventListener('change',update);update();}
 return{student,teacher,studentReport,overview,bind};
}
